const signatures = {
  "curriculum-35f3a6570094-m1-s1-q1": "[\"Alternative Investments\",\"Learning Module 1 — Alternative Investment Features, Methods, and Structures\",\"Which of the following documents provides tailored terms for a specific investor?\",[{\"id\":\"A\",\"text\":\"A side letter\"},{\"id\":\"B\",\"text\":\"An excusal right\"},{\"id\":\"C\",\"text\":\"A limited partnership agreement\"}],\"A\",\"The correct answer is A. In addition to limited partnership agreements (LPAs), a supplemental document known as a side letter also may be negotiated. Side letters are agreements between the general partner and one or more limited partners that exist outside the LPA and whose terms override or modify the original limited partnership agreement terms. A side letter is negotiated to address the unique legal, regulatory, or reporting requirements of a specific investor. B is incorrect because an excusal right gives an investor the right to forgo a capital contribution or to not participate in a particular type of investment. An excusal right is granted when it has been stipulated in a side letter, not independently. C is incorrect because the limited partnership agreement establishes and governs the terms of a limited partnership; its terms apply to all limited partners, not just to a specific investor who requires tailored terms.\",[{\"category\":\"curriculum\",\"title\":\"ALTERNATIVE INVESTMENTS\",\"edition\":\"CFA Program Curriculum 2027, May 2026\",\"year\":\"2027\",\"location\":\"Learning Module 1 — Alternative Investment Features, Methods, and Structures; Practice Problems; Q1; PDF pages 37\",\"answerLocation\":\"Practice Problems; answer 1; PDF pages 39\"}],[{\"id\":\"original-question\",\"type\":\"document\",\"pages\":[{\"pdfPage\":37,\"src\":\"question-assets/35f3a6570094-p37.webp\"},{\"pdfPage\":38,\"src\":\"question-assets/35f3a6570094-p38.webp\"}],\"initialPage\":37,\"title\":\"ALTERNATIVE INVESTMENTS\"}],[\"original-question\"],[{\"id\":\"original-solution\",\"type\":\"document\",\"pages\":[{\"pdfPage\":39,\"src\":\"question-assets/35f3a6570094-p39.webp\"}],\"initialPage\":39,\"title\":\"ALTERNATIVE INVESTMENTS\"}],{\"candidateId\":\"curriculum-35f3a6570094-m1-s1-q1\",\"questionPages\":[37],\"sectionPages\":[37,38],\"answerPages\":[39],\"sourceSha256\":\"35f3a6570094485b78cd84d1ad29d6fba8d731e84c18aaad157c7d47f06a6c63\",\"issues\":[\"independent pdftotext comparison incomplete\"],\"sourcePracticeReady\":true,\"dualKeyAgreement\":true,\"keyEvidence\":\"The correct answer is A\",\"sharedRawText\":\"\",\"answerPageOverlap\":[],\"solutionHeadingPages\":[]},\"source\",true]",
  "curriculum-2bd17910ac94-m1-s1-q1": "[\"Corporate Issuers\",\"Learning Module 1 — Organizational Forms, Corporate Issuer Features, and Ownership\",\"What percentage of the timber and forest assets are effectively owned by the Dee family members in this scenario?\",[{\"id\":\"A\",\"text\":\"24%\"},{\"id\":\"B\",\"text\":\"30%\"},{\"id\":\"C\",\"text\":\"80%\"}],\"A\",\"A is correct. The Dee family effectively owns 24% of the timber and forest assets. They own 30% of the shares of DAG (the publicly traded corporation), and they own 80% of the limited partnership (which owns the assets): 24% = 30% × 80%.\",[{\"category\":\"curriculum\",\"title\":\"CORPORATE FINANCE\",\"edition\":\"CFA Program Curriculum 2027, May 2026\",\"year\":\"2027\",\"location\":\"Learning Module 1 — Organizational Forms, Corporate Issuer Features, and Ownership; Practice Problems; Q1; PDF pages 42\",\"answerLocation\":\"Practice Problems; answer 1; PDF pages 44\"}],[{\"id\":\"original-question\",\"type\":\"document\",\"pages\":[{\"pdfPage\":42,\"src\":\"question-assets/2bd17910ac94-p42.webp\"},{\"pdfPage\":43,\"src\":\"question-assets/2bd17910ac94-p43.webp\"}],\"initialPage\":42,\"title\":\"CORPORATE FINANCE\"}],[\"original-question\"],[{\"id\":\"original-solution\",\"type\":\"document\",\"pages\":[{\"pdfPage\":44,\"src\":\"question-assets/2bd17910ac94-p44.webp\"}],\"initialPage\":44,\"title\":\"CORPORATE FINANCE\"}],{\"candidateId\":\"curriculum-2bd17910ac94-m1-s1-q1\",\"questionPages\":[42],\"sectionPages\":[42,43],\"answerPages\":[44],\"sourceSha256\":\"2bd17910ac94bf13ef81c23c838c1c20f7bb0d2ba27e9a56004c4673ca7e4aa3\",\"issues\":[\"shared passage or section introduction requires verification\"],\"sourcePracticeReady\":true,\"dualKeyAgreement\":true,\"keyEvidence\":\"A is correct\",\"sharedRawText\":\"The following information relates to questions 1-5 Dee’s Arbor Group Inc. (DAG Inc.) is a large international investor in timber and forest assets located on the North and South American continents. DAG Inc. is the general partner of DAG LP, a limited partnership that is the 100% owner of the timber and forest assets. DAG LP is controlled by DAG Inc. and its limited partners; the limited partners own a 20% stake in the partnership, while DAG Inc. holds the remaining majority stake. DAG Inc.’s shares are listed on stock exchanges in the United States and Canada. DAG Inc. is organized as a special corporate form available in its jurisdiction in which it does not pay corporate income taxes so long as it distributes all of its net income as dividends to its shareholders and complies with other conditions. In the current and past fiscal years, DAG Inc. has complied with all of these conditions. DAG Inc.’s shares are owned by various members of the Dee family, who hold several key senior management positions at DAG Inc. and DAG LP, and collectively they own 30% of the shares of DAG Inc. The remainder of DAG Inc.’s shares are owned by a variety of individual and institutional investors, none of whom own more than 5%. The following diagram shows the organizational structure of DAG Inc. and DAG LP. Dee Family Members Outside Shareholders Timber and Forest Assets DAG LP DAG Inc. Limited Partners\",\"answerPageOverlap\":[],\"solutionHeadingPages\":[]},\"source\",true]",
  "schweser-4e41f3d725f8-m20-s1-q1": "[\"Derivatives\",\"Module Quiz 70.1: Derivative Instrument and Derivative Market Features\",\"Which of the following statements most accurately describes a derivative security? A derivative:\",[{\"id\":\"A\",\"text\":\"always increases risk.\"},{\"id\":\"B\",\"text\":\"has no expiration date.\"},{\"id\":\"C\",\"text\":\"has a payoff based on an asset value or interest rate.\"}],\"C\",\"A derivative’s value is derived from another asset or an interest rate. (LOS 70.a)\",[{\"category\":\"schweser\",\"title\":\"SCHWESERNOTES™ 2027 LEVEL I CFA® BOOK 3: FIXED INCOME AND DERIVATIVES\",\"edition\":\"SchweserNotes 2027\",\"year\":\"2027\",\"location\":\"Reading 70 Derivative Instrument and Derivative Market Features; Module Quiz 70.1; Q1; PDF pages 207\",\"answerLocation\":\"Module Quiz 70.1; answer 1; PDF pages 208\"}],[{\"id\":\"original-question\",\"type\":\"document\",\"pages\":[{\"pdfPage\":207,\"src\":\"question-assets/4e41f3d725f8-p207.webp\"}],\"initialPage\":207,\"title\":\"SCHWESERNOTES™ 2027 LEVEL I CFA® BOOK 3: FIXED INCOME AND DERIVATIVES\"}],[\"original-question\"],[{\"id\":\"original-solution\",\"type\":\"document\",\"pages\":[{\"pdfPage\":208,\"src\":\"question-assets/4e41f3d725f8-p208.webp\"}],\"initialPage\":208,\"title\":\"SCHWESERNOTES™ 2027 LEVEL I CFA® BOOK 3: FIXED INCOME AND DERIVATIVES\"}],{\"candidateId\":\"schweser-4e41f3d725f8-m20-s1-q1\",\"questionPages\":[207],\"sectionPages\":[207],\"answerPages\":[208],\"sourceSha256\":\"4e41f3d725f84e89001b5137306d65481ad72c6213da0075fc1c04c4659a1087\",\"issues\":[\"possible table, passage or cross-question context\"],\"sourcePracticeReady\":true,\"dualKeyAgreement\":true,\"keyEvidence\":\"C\",\"sharedRawText\":\"\",\"answerPageOverlap\":[],\"solutionHeadingPages\":[]},\"source\",true]",
  "schweser-17f6dfc8a2a4-m12-s1-q1": "[\"Economics\",\"Module Quiz 12.1: The Firm and Market Structures\",\"In a purely competitive market, economic losses indicate that:\",[{\"id\":\"A\",\"text\":\"price is below average total costs.\"},{\"id\":\"B\",\"text\":\"collusion is occurring in the marketplace.\"},{\"id\":\"C\",\"text\":\"firms need to expand output to reduce costs.\"}],\"A\",\"In a purely competitive market, economic losses indicate that firms are overproducing, causing prices to fall below average total costs. This can occur in the short run. In the long run, however, market supply will decrease as firms exit the industry, and prices will rise to the point where economic profits are zero. (LOS 12.a)\",[{\"category\":\"schweser\",\"title\":\"SCHWESERNOTES™ 2027 LEVEL I CFA® BOOK 1: QUANTITATIVE METHODS, ECONOMICS, AND CORPORATE FINANCE\",\"edition\":\"SchweserNotes 2027\",\"year\":\"2027\",\"location\":\"Reading 12 The Firm and Market Structures; Module Quiz 12.1; Q1; PDF pages 288\",\"answerLocation\":\"Module Quiz 12.1; answer 1; PDF pages 306\"}],[{\"id\":\"original-question\",\"type\":\"document\",\"pages\":[{\"pdfPage\":288,\"src\":\"question-assets/17f6dfc8a2a4-p288.webp\"},{\"pdfPage\":289,\"src\":\"question-assets/17f6dfc8a2a4-p289.webp\"}],\"initialPage\":288,\"title\":\"SCHWESERNOTES™ 2027 LEVEL I CFA® BOOK 1: QUANTITATIVE METHODS, ECONOMICS, AND CORPORATE FINANCE\"}],[\"original-question\"],[{\"id\":\"original-solution\",\"type\":\"document\",\"pages\":[{\"pdfPage\":306,\"src\":\"question-assets/17f6dfc8a2a4-p306.webp\"}],\"initialPage\":306,\"title\":\"SCHWESERNOTES™ 2027 LEVEL I CFA® BOOK 1: QUANTITATIVE METHODS, ECONOMICS, AND CORPORATE FINANCE\"}],{\"candidateId\":\"schweser-17f6dfc8a2a4-m12-s1-q1\",\"questionPages\":[288],\"sectionPages\":[288,289],\"answerPages\":[306],\"sourceSha256\":\"17f6dfc8a2a433addd511f17d9654a5a5e4948fe76cc2297d65bd3713b575f94\",\"issues\":[],\"sourcePracticeReady\":true,\"dualKeyAgreement\":true,\"keyEvidence\":\". A\",\"sharedRawText\":\"\",\"answerPageOverlap\":[],\"solutionHeadingPages\":[]},\"source\",true]",
  "curriculum-d762de00aeec-m1-s1-q1": "[\"Equity Investments\",\"Learning Module 1 — Equity Instrument Features\",\"Which of the following securities has the lowest seniority on claiming cash flows from a portfolio company?\",[{\"id\":\"A\",\"text\":\"Debt\"},{\"id\":\"B\",\"text\":\"Preference shares\"},{\"id\":\"C\",\"text\":\"Common shares\"}],\"C\",\"Choice C is correct. Holders of common shares have the residual claim on a company’s cash flows and assets. Common shareholders are paid once all other claims are settled. Choice A is incorrect as debtholders have the highest seniority in receiving cash flows relative to preference and common shareholders. Choice B is incorrect as preference shareholders are senior to common shareholders.\",[{\"category\":\"curriculum\",\"title\":\"EQUITIES\",\"edition\":\"CFA Program Curriculum 2027, May 2026\",\"year\":\"2027\",\"location\":\"Learning Module 1 — Equity Instrument Features; Practice Problems; Q1; PDF pages 32\",\"answerLocation\":\"Practice Problems; answer 1; PDF pages 34\"}],[{\"id\":\"original-question\",\"type\":\"document\",\"pages\":[{\"pdfPage\":32,\"src\":\"question-assets/d762de00aeec-p32.webp\"},{\"pdfPage\":33,\"src\":\"question-assets/d762de00aeec-p33.webp\"}],\"initialPage\":32,\"title\":\"EQUITIES\"}],[\"original-question\"],[{\"id\":\"original-solution\",\"type\":\"document\",\"pages\":[{\"pdfPage\":34,\"src\":\"question-assets/d762de00aeec-p34.webp\"}],\"initialPage\":34,\"title\":\"EQUITIES\"}],{\"candidateId\":\"curriculum-d762de00aeec-m1-s1-q1\",\"questionPages\":[32],\"sectionPages\":[32,33],\"answerPages\":[34],\"sourceSha256\":\"d762de00aeecbcfc62b1bc7815d487b2476ab17c22cc2f43cf0a8eab1c18f1ca\",\"issues\":[\"shared passage or section introduction requires verification\"],\"sourcePracticeReady\":true,\"dualKeyAgreement\":true,\"keyEvidence\":\"Choice C is correct\",\"sharedRawText\":\"The following information relates to questions 1-4 Audrey Lake is the Chief Investment Officer of Mid States University Management Corporation (MSUMC), an endowment fund overseeing the university’s investment portfolio. MSUMC invests over half of its assets in equity securities, both public and private. As part of the equity review process, Lake has assigned the analyst team questions to consider. First, MSUMC’s Investment Office is more interested in being able to benefit from improved company performance than the seniority of claims when they invest. Second, MSUMC’s Investment Office seeks a “voice” in management decisions of the companies in which they invest. Third, MSUMC targets broad exposure across the equity universe, buying both publicly listed and private equities across company life-cycle stages. Finally, MSUMC has a very long investment horizon.\",\"answerPageOverlap\":[],\"solutionHeadingPages\":[]},\"source\",true]",
  "curriculum-644fa6daeebb-m1-s1-q1": "[\"Ethical and Professional Standards\",\"Learning Module 1 — Ethics and Trust in the Investment Profession\",\"Benchmarks for minimally acceptable behaviors of community members are:\",[{\"id\":\"A\",\"text\":\"a code of ethics.\"},{\"id\":\"B\",\"text\":\"laws and regulations.\"},{\"id\":\"C\",\"text\":\"standards of conduct.\"}],\"C\",\"C is correct. Standards of conduct are applied to specific communities or societal groups and identify specific behaviors required of community members. These standards of conduct serve as benchmarks for the minimally acceptable behavior of community members. Codes of ethics serve as a general guide for how community members should act; they communicate the organization’s values and overall expectations regarding member behavior, but they do not identify specific behaviors required of community members. Laws and regulations are rules of conduct defined by governments and related entities about obligatory and forbidden conduct broadly applicable for individuals and entities under their jurisdiction.\",[{\"category\":\"curriculum\",\"title\":\"ETHICAL AND PROFESSIONAL STANDARDS\",\"edition\":\"CFA Program Curriculum 2027, May 2026\",\"year\":\"2027\",\"location\":\"Learning Module 1 — Ethics and Trust in the Investment Profession; Practice Problems; Q1; PDF pages 43\",\"answerLocation\":\"Practice Problems; answer 1; PDF pages 45\"}],[{\"id\":\"original-question\",\"type\":\"document\",\"pages\":[{\"pdfPage\":43,\"src\":\"question-assets/644fa6daeebb-p43.webp\"},{\"pdfPage\":44,\"src\":\"question-assets/644fa6daeebb-p44.webp\"}],\"initialPage\":43,\"title\":\"ETHICAL AND PROFESSIONAL STANDARDS\"}],[\"original-question\"],[{\"id\":\"original-solution\",\"type\":\"document\",\"pages\":[{\"pdfPage\":45,\"src\":\"question-assets/644fa6daeebb-p45.webp\"}],\"initialPage\":45,\"title\":\"ETHICAL AND PROFESSIONAL STANDARDS\"}],{\"candidateId\":\"curriculum-644fa6daeebb-m1-s1-q1\",\"questionPages\":[43],\"sectionPages\":[43,44],\"answerPages\":[45],\"sourceSha256\":\"644fa6daeebb165f236b0f556b5643c3397fc0c7c0c8a6845a9da2a9893ff31e\",\"issues\":[\"independent pdftotext comparison incomplete\"],\"sourcePracticeReady\":true,\"dualKeyAgreement\":true,\"keyEvidence\":\"C is correct\",\"sharedRawText\":\"\",\"answerPageOverlap\":[],\"solutionHeadingPages\":[]},\"source\",true]",
  "curriculum-b84e7a955d95-m1-s1-q1": "[\"Financial Statement Analysis\",\"Learning Module 1 — Introduction to Financial Statement Analysis\",\"Ratios are an input into which step in the financial statement analysis framework?\",[{\"id\":\"A\",\"text\":\"Process data\"},{\"id\":\"B\",\"text\":\"Collect input data\"},{\"id\":\"C\",\"text\":\"Analyze/interpret the processed data\"}],\"C\",\"C is correct. Ratios are an output of the process information step but are an input into the analyze/interpret data step.\",[{\"category\":\"curriculum\",\"title\":\"FINANCIAL STATEMENT ANALYSIS\",\"edition\":\"CFA Program Curriculum 2027, May 2026\",\"year\":\"2027\",\"location\":\"Learning Module 1 — Introduction to Financial Statement Analysis; Practice Problems; Q1; PDF pages 44\",\"answerLocation\":\"Practice Problems; answer 1; PDF pages 47\"}],[{\"id\":\"original-question\",\"type\":\"document\",\"pages\":[{\"pdfPage\":44,\"src\":\"question-assets/b84e7a955d95-p44.webp\"},{\"pdfPage\":45,\"src\":\"question-assets/b84e7a955d95-p45.webp\"},{\"pdfPage\":46,\"src\":\"question-assets/b84e7a955d95-p46.webp\"}],\"initialPage\":44,\"title\":\"FINANCIAL STATEMENT ANALYSIS\"}],[\"original-question\"],[{\"id\":\"original-solution\",\"type\":\"document\",\"pages\":[{\"pdfPage\":47,\"src\":\"question-assets/b84e7a955d95-p47.webp\"}],\"initialPage\":47,\"title\":\"FINANCIAL STATEMENT ANALYSIS\"}],{\"candidateId\":\"curriculum-b84e7a955d95-m1-s1-q1\",\"questionPages\":[44],\"sectionPages\":[44,45,46],\"answerPages\":[47],\"sourceSha256\":\"b84e7a955d951b7fe77bb8719bd1d1181a9a223e96913ba89ca18a438ca7d6e7\",\"issues\":[],\"sourcePracticeReady\":true,\"dualKeyAgreement\":true,\"keyEvidence\":\"C is correct\",\"sharedRawText\":\"\",\"answerPageOverlap\":[],\"solutionHeadingPages\":[]},\"source\",true]",
  "curriculum-a26bb009cb63-m2-s1-q1": "[\"Fixed Income\",\"Learning Module 2 — Fixed-Income Cash Flows and Types\",\"Which of the following statements best describes the type of bonds to be issued given the issuer’s country and where the bonds will be issued and traded?\",[{\"id\":\"A\",\"text\":\"Since Digistrype is planning to issue and sell euro-denominated bonds, its bonds would be considered Eurobonds.\"},{\"id\":\"B\",\"text\":\"Since Digistrype is planning to issue and sell euro-denominated bonds to investors in Germany, its bonds would be considered foreign bonds.\"},{\"id\":\"C\",\"text\":\"Since Digistrype is planning to issue and sell bonds to domestic investors in Germany, its bonds would be considered domestic bonds.\"}],\"B\",\"B is correct. Digistrype, a Canadian firm, is planning to issue and sell euro-denominated bonds to investors in Germany. Bonds issued by entities that are incorporated in another country are called foreign bonds. A is incorrect because Eurobonds are cross-border bonds that are not necessarily denominated in euros. C is incorrect because domestic bonds refer to a domestic issuer, not investor.\",[{\"category\":\"curriculum\",\"title\":\"FIXED INCOME\",\"edition\":\"CFA Program Curriculum 2027, May 2026\",\"year\":\"2027\",\"location\":\"Learning Module 2 — Fixed-Income Cash Flows and Types; Practice Problems; Q1; PDF pages 61\",\"answerLocation\":\"Practice Problems; answer 1; PDF pages 63\"}],[{\"id\":\"original-question\",\"type\":\"document\",\"pages\":[{\"pdfPage\":61,\"src\":\"question-assets/a26bb009cb63-p61.webp\"},{\"pdfPage\":62,\"src\":\"question-assets/a26bb009cb63-p62.webp\"}],\"initialPage\":61,\"title\":\"FIXED INCOME\"}],[\"original-question\"],[{\"id\":\"original-solution\",\"type\":\"document\",\"pages\":[{\"pdfPage\":63,\"src\":\"question-assets/a26bb009cb63-p63.webp\"}],\"initialPage\":63,\"title\":\"FIXED INCOME\"}],{\"candidateId\":\"curriculum-a26bb009cb63-m2-s1-q1\",\"questionPages\":[61],\"sectionPages\":[61,62],\"answerPages\":[63],\"sourceSha256\":\"a26bb009cb63e72d8643657ebc3cfb21ec9e7438e51cbde47666d63a4b663b14\",\"issues\":[\"shared passage or section introduction requires verification\",\"possible table, passage or cross-question context\"],\"sourcePracticeReady\":true,\"dualKeyAgreement\":true,\"keyEvidence\":\"B is correct\",\"sharedRawText\":\"The following information relates to questions 1-5 Digistrype Logistics (DILO) is a Canadian firm that generates a large portion of revenue in Europe. To finance its planned expansion into digital logistics, DILO is seeking to issue euro-denominated bonds to institutional investors in Germany. A term sheet for the proposed bond issue is presented below. 1.25% Digistrype Logistics (DILO) Seven-Year Convertible Notes (the “Notes”) Term Sheet Issuer: Digistrype Logistics Inc. Settlement Date: [T + 3 Business Days] Maturity Date: Seven Years from Settlement Date unless the Notes are redeemed earlier in a Conversion Principal Amount: EUR250 million Unit Size: EUR1,000 per bond Interest: 3.25% fixed coupon to be paid annually starting one Year from the Settlement Date with the final coupon paid at Maturity Seniority: The Notes are an unsecured obligation of DILO and rank pari passu with other unsecured debt. Conversion Provision: An Investor has, at its sole option, the right to convert a portion or the full sum of the Principal Amount, or any part outstanding at any time at the Conversion Price during the Conversion Period. Current Share Price: EUR60.00 per DILO common equity share Conversion Price: EUR75.00 per DILO common equity share Conversion Period: Any Business Day starting from the Settlement Date through the Maturity Date Institutional investors have expressed concern about increased credit risk due to Digistrype’s planned expansion outside of its core business. Digistrype’s CFO would prefer to fund the expansion using debt, despite an expectation of lower market interest rates in the next few years. The CFO is also considering removing the conversion feature because of a concern about the possible share dilution if the bonds are converted to equity and a belief that DILO shares are significantly undervalued.\",\"answerPageOverlap\":[],\"solutionHeadingPages\":[]},\"source\",true]",
  "curriculum-8ddcb46a0224-m1-s1-q1": "[\"Portfolio Management\",\"Learning Module 1 — Portfolio Risk and Return: Part I\",\"With respect to trading costs, liquidity is least likely to impact the:\",[{\"id\":\"A\",\"text\":\"stock price.\"},{\"id\":\"B\",\"text\":\"bid–ask spreads.\"},{\"id\":\"C\",\"text\":\"brokerage commissions.\"}],\"C\",\"C is correct. Brokerage commissions are negotiated with the brokerage firm. A security’s liquidity impacts the operational efficiency of trading costs. Specifically, liquidity impacts the bid–ask spread and can impact the stock price (if the ability to sell the stock is impaired by the uncertainty associated with being able to sell the stock).\",[{\"category\":\"curriculum\",\"title\":\"PORTFOLIO CONSTRUCTION\",\"edition\":\"CFA Program Curriculum 2027, May 2026\",\"year\":\"2027\",\"location\":\"Learning Module 1 — Portfolio Risk and Return: Part I; Practice Problems; Q1; PDF pages 60\",\"answerLocation\":\"Practice Problems; answer 1; PDF pages 67\"}],[{\"id\":\"original-question\",\"type\":\"document\",\"pages\":[{\"pdfPage\":60,\"src\":\"question-assets/8ddcb46a0224-p60.webp\"},{\"pdfPage\":61,\"src\":\"question-assets/8ddcb46a0224-p61.webp\"},{\"pdfPage\":62,\"src\":\"question-assets/8ddcb46a0224-p62.webp\"},{\"pdfPage\":63,\"src\":\"question-assets/8ddcb46a0224-p63.webp\"},{\"pdfPage\":64,\"src\":\"question-assets/8ddcb46a0224-p64.webp\"},{\"pdfPage\":65,\"src\":\"question-assets/8ddcb46a0224-p65.webp\"},{\"pdfPage\":66,\"src\":\"question-assets/8ddcb46a0224-p66.webp\"}],\"initialPage\":60,\"title\":\"PORTFOLIO CONSTRUCTION\"}],[\"original-question\"],[{\"id\":\"original-solution\",\"type\":\"document\",\"pages\":[{\"pdfPage\":67,\"src\":\"question-assets/8ddcb46a0224-p67.webp\"}],\"initialPage\":67,\"title\":\"PORTFOLIO CONSTRUCTION\"}],{\"candidateId\":\"curriculum-8ddcb46a0224-m1-s1-q1\",\"questionPages\":[60],\"sectionPages\":[60,61,62,63,64,65,66],\"answerPages\":[67],\"sourceSha256\":\"8ddcb46a0224207a998ea88510648feca65e0a377321dcb3fc20fa7ff7bc5646\",\"issues\":[],\"sourcePracticeReady\":true,\"dualKeyAgreement\":true,\"keyEvidence\":\"C is correct\",\"sharedRawText\":\"\",\"answerPageOverlap\":[],\"solutionHeadingPages\":[]},\"source\",true]",
  "cfa-2027-v6-lm1-q1": "[\"Fixed Income\",\"Fixed-Income Instrument Features\",\"“Four years” and “MRR plus 250 bps p.a.” refer, respectively, to which bond features as of the settlement date?\",[{\"id\":\"A\",\"text\":\"Time to maturity and coupon rate\"},{\"id\":\"B\",\"text\":\"Coupon frequency and current yield\"},{\"id\":\"C\",\"text\":\"Time to maturity and contingency provision\"}],\"A\",\"A is correct. The notes mature (the date Antelas AG will pay the final coupon and principal amount) four years after the trade settlement date, and the coupon rate is variable, determined by the MRR plus a fixed 250 bp spread.\",[{\"category\":\"curriculum\",\"title\":\"CFA Program Curriculum 2027 Level I Volume 6: Fixed Income\",\"edition\":\"2027\",\"year\":\"2027\",\"location\":\"Practice Problems Q1; printed pp. 20–21; PDF pp. 30–31; shared passage/table PDF p. 30\",\"answerLocation\":\"Solutions Q1; printed p. 22; PDF p. 32\"}],[{\"id\":\"antelas-passage\",\"type\":\"passage\",\"text\":\"Antelas AG is a German emerging technology company focused on manufacturing process design. The firm has developed several valuable patents related to micromachining and metal 3D printing technology and derives its revenue through licensing royalties and consultation services. Antelas recently issued the following debt instrument:\"},{\"id\":\"antelas-table\",\"type\":\"image\",\"alt\":\"Antelas AG Four-Year Floating-Rate Notes (The “Notes”) — Prospectus Summary\",\"src\":\"data:image/png;base64,\"}],[\"antelas-passage\",\"antelas-table\"],null,null,null,true]",
  "cfa-2027-v6-lm1-q2": "[\"Fixed Income\",\"Fixed-Income Instrument Features\",\"Which of the following statements best describes the source(s) of repayment for the Antelas AG floating-rate notes?\",[{\"id\":\"A\",\"text\":\"Since the notes are secured (or backed) by Antelas AG’s assets, the floating-rate notes would be considered asset-backed securities.\"},{\"id\":\"B\",\"text\":\"The Antelas AG notes rely on the operating cash flows of the firm as their sole source for interest and principal payments.\"},{\"id\":\"C\",\"text\":\"The Antelas AG notes rely on the operating cash flows of the firm as their primary source for interest and principal payments.\"}],\"C\",\"C is correct. Secured corporate bonds rely on the operating cash flows of the firm as their primary source for interest and principal payments and a legal claim on assets as a secondary source of payment. A is incorrect because asset-backed securities (ABS) are issued by special-purpose entities created to take ownership in loans or receivables, the cash flows from which are used to pay interest and principal to investors. B is incorrect because it describes unsecured, not secured, corporate debt.\",[{\"category\":\"curriculum\",\"title\":\"CFA Program Curriculum 2027 Level I Volume 6: Fixed Income\",\"edition\":\"2027\",\"year\":\"2027\",\"location\":\"Practice Problems Q2; printed pp. 20–21; PDF pp. 30–31; shared passage/table PDF p. 30\",\"answerLocation\":\"Solutions Q2; printed p. 22; PDF p. 32\"}],[{\"id\":\"antelas-passage\",\"type\":\"passage\",\"text\":\"Antelas AG is a German emerging technology company focused on manufacturing process design. The firm has developed several valuable patents related to micromachining and metal 3D printing technology and derives its revenue through licensing royalties and consultation services. Antelas recently issued the following debt instrument:\"},{\"id\":\"antelas-table\",\"type\":\"image\",\"alt\":\"Antelas AG Four-Year Floating-Rate Notes (The “Notes”) — Prospectus Summary\",\"src\":\"data:image/png;base64,\"}],[\"antelas-passage\",\"antelas-table\"],null,null,null,true]",
  "cfa-2027-v6-lm1-q3": "[\"Fixed Income\",\"Fixed-Income Instrument Features\",\"Antelas AG’s issuer-specific credit spread rises by 25 bps p.a. one year after the FRN issuance. Which of the following best describes how Antelas AG’s FRN coupon would change as a result?\",[{\"id\":\"A\",\"text\":\"Antelas AG’s FRN coupon payment to investors will immediately increase by 25 bps p.a.\"},{\"id\":\"B\",\"text\":\"Antelas AG’s FRN coupon payment to investors will increase by 25 bps p.a. but will not become effective until the next full debt coupon period begins.\"},{\"id\":\"C\",\"text\":\"Antelas AG’s FRN coupon will remain unchanged.\"}],\"C\",\"C is correct. For the Antelas AG FRN, the spread is fixed at 250 bps and the coupon will only change with changes in the MRR.\",[{\"category\":\"curriculum\",\"title\":\"CFA Program Curriculum 2027 Level I Volume 6: Fixed Income\",\"edition\":\"2027\",\"year\":\"2027\",\"location\":\"Practice Problems Q3; printed pp. 20–21; PDF pp. 30–31; shared passage/table PDF p. 30\",\"answerLocation\":\"Solutions Q3; printed p. 22; PDF p. 32\"}],[{\"id\":\"antelas-passage\",\"type\":\"passage\",\"text\":\"Antelas AG is a German emerging technology company focused on manufacturing process design. The firm has developed several valuable patents related to micromachining and metal 3D printing technology and derives its revenue through licensing royalties and consultation services. Antelas recently issued the following debt instrument:\"},{\"id\":\"antelas-table\",\"type\":\"image\",\"alt\":\"Antelas AG Four-Year Floating-Rate Notes (The “Notes”) — Prospectus Summary\",\"src\":\"data:image/png;base64,\"}],[\"antelas-passage\",\"antelas-table\"],null,null,null,true]",
  "cfa-2027-v6-lm1-q4": "[\"Fixed Income\",\"Fixed-Income Instrument Features\",\"Calculate the value of Antelas’s payment to bondholders on the maturity date if the MRR is 0.25% p.a. for the final interest period.\",[{\"id\":\"A\",\"text\":\"EUR1,718,750\"},{\"id\":\"B\",\"text\":\"EUR251,718,750\"},{\"id\":\"C\",\"text\":\"EUR256,875,000\"}],\"B\",\"B is correct. On the maturity date, Antelas AG pays investors the final FRN coupon payment plus the bond’s principal amount. The FRN coupon comprises MRR plus the issuer-specific spread. ■ FRN coupon rate: MRR plus spread, or 0.25% + 2.50%= 2.75% ■ Annual interest expense: Principal × FRN coupon, or €EUR250,000,000 × 2.75% = EUR6,875,000 ■ Quarterly interest expense: Annual interest expense/4, or EUR6,875,000/4 = EUR1,718,750 ■ Principal Amount: EUR250,000,000 ■ Total Payment = EUR250,000,000 + EUR1,718,750 = 251,718,750\",[{\"category\":\"curriculum\",\"title\":\"CFA Program Curriculum 2027 Level I Volume 6: Fixed Income\",\"edition\":\"2027\",\"year\":\"2027\",\"location\":\"Practice Problems Q4; printed pp. 20–21; PDF pp. 30–31; shared passage/table PDF p. 30\",\"answerLocation\":\"Solutions Q4; printed p. 22; PDF p. 32\"}],[{\"id\":\"antelas-passage\",\"type\":\"passage\",\"text\":\"Antelas AG is a German emerging technology company focused on manufacturing process design. The firm has developed several valuable patents related to micromachining and metal 3D printing technology and derives its revenue through licensing royalties and consultation services. Antelas recently issued the following debt instrument:\"},{\"id\":\"antelas-table\",\"type\":\"image\",\"alt\":\"Antelas AG Four-Year Floating-Rate Notes (The “Notes”) — Prospectus Summary\",\"src\":\"data:image/png;base64,\"}],[\"antelas-passage\",\"antelas-table\"],null,null,null,true]",
  "cfa-2027-v6-lm1-q5": "[\"Fixed Income\",\"Fixed-Income Instrument Features\",\"Antelas decides to raise new secured, unsubordinated debt. Which of the following best describes the priority of payments between the issuer’s new debt and its existing debt?\",[{\"id\":\"A\",\"text\":\"Because the Antelas AG notes have a pari passu (or “equal footing”) clause, this debt obligation will be treated the same as any other secured, unsubordinated debt from this borrower.\"},{\"id\":\"B\",\"text\":\"Because the existing debt was issued earlier, it would receive priority over the new debt in terms of the payment of interest and principal.\"},{\"id\":\"C\",\"text\":\"We do not have enough information to answer this question; the necessary information would be provided in the indenture for new secured, unsubordinated notes.\"}],\"A\",\"A is correct. Antelas AG’s existing secured, unsubordinated debt has a pari passu (or “equal footing”) clause, which ensures that this debt obligation will be treated the same as any other secured, unsubordinated debt from this borrower. B is incorrect because the priority of payments is unrelated to the timing of issuance. C is incorrect because the pari passu clause ensures equal footing for similar new debt.\",[{\"category\":\"curriculum\",\"title\":\"CFA Program Curriculum 2027 Level I Volume 6: Fixed Income\",\"edition\":\"2027\",\"year\":\"2027\",\"location\":\"Practice Problems Q5; printed pp. 20–21; PDF pp. 30–31; shared passage/table PDF p. 30\",\"answerLocation\":\"Solutions Q5; printed p. 22; PDF p. 32\"}],[{\"id\":\"antelas-passage\",\"type\":\"passage\",\"text\":\"Antelas AG is a German emerging technology company focused on manufacturing process design. The firm has developed several valuable patents related to micromachining and metal 3D printing technology and derives its revenue through licensing royalties and consultation services. Antelas recently issued the following debt instrument:\"},{\"id\":\"antelas-table\",\"type\":\"image\",\"alt\":\"Antelas AG Four-Year Floating-Rate Notes (The “Notes”) — Prospectus Summary\",\"src\":\"data:image/png;base64,\"}],[\"antelas-passage\",\"antelas-table\"],null,null,null,true]",
  "schweser-2027-b3-m51.1-q1": "[\"Fixed Income\",\"Module 51.1: Fixed-Income Instrument Features\",\"A fixed-coupon bond will pay a coupon equal to its:\",[{\"id\":\"A\",\"text\":\"yield multiplied by price.\"},{\"id\":\"B\",\"text\":\"stated coupon rate multiplied by price.\"},{\"id\":\"C\",\"text\":\"stated coupon rate multiplied by face value.\"}],\"C\",\"A fixed-coupon bond has a stated coupon rate that is applied to the bond’s face (principal or par) value. The yield of the bond is the return earned through paying the bond’s price today and holding the bond to maturity. (LOS 51.a)\",[{\"category\":\"schweser\",\"title\":\"SchweserNotes 2027 Level I CFA Book 3: Fixed Income and Derivatives\",\"edition\":\"2027\",\"year\":\"2027\",\"location\":\"Module Quiz 51.1 Q1; PDF p. 19\",\"answerLocation\":\"Module Quiz 51.1 answer entry 1; PDF p. 20\"}],[],[],null,null,null,true]",
  "schweser-2027-b3-m51.1-q2": "[\"Fixed Income\",\"Module 51.1: Fixed-Income Instrument Features\",\"When fixed-coupon bond prices fall:\",[{\"id\":\"A\",\"text\":\"their yields rise.\"},{\"id\":\"B\",\"text\":\"their yields fall.\"},{\"id\":\"C\",\"text\":\"their coupon rates fall.\"}],\"A\",\"For fixed-coupon bonds, prices and yields have an inverse relationship. If the price of the bond is falling, then the return (yield) from buying the bond at the lower price is rising. (LOS 51.a)\",[{\"category\":\"schweser\",\"title\":\"SchweserNotes 2027 Level I CFA Book 3: Fixed Income and Derivatives\",\"edition\":\"2027\",\"year\":\"2027\",\"location\":\"Module Quiz 51.1 Q2; PDF p. 19\",\"answerLocation\":\"Module Quiz 51.1 answer entry 2; PDF p. 20\"}],[],[],null,null,null,true]",
  "schweser-2027-b3-m51.1-q3": "[\"Fixed Income\",\"Module 51.1: Fixed-Income Instrument Features\",\"A bond’s indenture:\",[{\"id\":\"A\",\"text\":\"contains its covenants.\"},{\"id\":\"B\",\"text\":\"is only required in the event of a lien on collateral.\"},{\"id\":\"C\",\"text\":\"relates only to its interest and principal payments.\"}],\"A\",\"An indenture is the contract between the company and its bondholders and contains the bond’s covenants. (LOS 51.b)\",[{\"category\":\"schweser\",\"title\":\"SchweserNotes 2027 Level I CFA Book 3: Fixed Income and Derivatives\",\"edition\":\"2027\",\"year\":\"2027\",\"location\":\"Module Quiz 51.1 Q3; PDF p. 19\",\"answerLocation\":\"Module Quiz 51.1 answer entry 3; PDF p. 21\"}],[],[],null,null,null,true]",
  "schweser-2027-b3-m51.1-q4": "[\"Fixed Income\",\"Module 51.1: Fixed-Income Instrument Features\",\"A clause in a bond indenture that requires the borrower to perform a certain action is most accurately described as a(n):\",[{\"id\":\"A\",\"text\":\"trust deed.\"},{\"id\":\"B\",\"text\":\"negative covenant.\"},{\"id\":\"C\",\"text\":\"affirmative covenant.\"}],\"C\",\"Affirmative covenants require the borrower to perform certain actions. Negative covenants restrict the borrower from performing certain actions. Trust deed is another name for a bond indenture. (LOS 51.b)\",[{\"category\":\"schweser\",\"title\":\"SchweserNotes 2027 Level I CFA Book 3: Fixed Income and Derivatives\",\"edition\":\"2027\",\"year\":\"2027\",\"location\":\"Module Quiz 51.1 Q4; PDF p. 19\",\"answerLocation\":\"Module Quiz 51.1 answer entry 4; PDF p. 21\"}],[],[],null,null,null,true]",
  "schweser-2027-b3-m56.1-q1": "[\"Fixed Income\",\"Module 56.1: Fixed-Income Bond Valuation: Prices and Yields\",\"A 20-year bond has a 10% annual-pay coupon. What is the price of the bond if it has a yield to maturity of 15%?\",[{\"id\":\"A\",\"text\":\"68.514.\"},{\"id\":\"B\",\"text\":\"68.703.\"},{\"id\":\"C\",\"text\":\"82.839.\"}],\"B\",\"N = 20; I/Y = 15; FV = 100; PMT = 10; and CPT → PV = −68.703 (LOS 56.a)\",[{\"category\":\"schweser\",\"title\":\"SchweserNotes 2027 Level I CFA Book 3: Fixed Income and Derivatives\",\"edition\":\"2027\",\"year\":\"2027\",\"location\":\"Module Quiz 56.1 Q1; PDF p. 72\",\"answerLocation\":\"Module Quiz 56.1 answer entry 1; PDF p. 74\"}],[],[],null,null,null,true]",
  "schweser-2027-b3-m56.1-q6": "[\"Fixed Income\",\"Module 56.1: Fixed-Income Bond Valuation: Prices and Yields\",\"Cathy Moran, CFA, is estimating a value for an infrequently traded bond with six years to maturity, an annual coupon of 7%, and a single-B credit rating. Moran obtains yields to maturity for more liquid bonds with the same credit rating: 5% coupon, eight years to maturity, yielding 7.20%. 6.5% coupon, five years to maturity, yielding 6.40%. The infrequently traded bond is most likely trading at:\",[{\"id\":\"A\",\"text\":\"par value.\"},{\"id\":\"B\",\"text\":\"a discount to par value.\"},{\"id\":\"C\",\"text\":\"a premium to par value.\"}],\"C\",\"Using linear interpolation, the yield on a bond with six years to maturity should be 6.40% + (1 / 3)(7.20% − 6.40%) = 6.67%. A bond with a 7% coupon and a yield of 6.67% is at a premium to par value. (LOS 56.c)\",[{\"category\":\"schweser\",\"title\":\"SchweserNotes 2027 Level I CFA Book 3: Fixed Income and Derivatives\",\"edition\":\"2027\",\"year\":\"2027\",\"location\":\"Module Quiz 56.1 Q6; PDF p. 73\",\"answerLocation\":\"Module Quiz 56.1 answer entry 6; PDF p. 75\"}],[],[],null,null,null,true]"
};
export function hasVerifiedSourceExplanation(q) {
  return !!q && typeof signatures[q.id] === 'string' && signatures[q.id] === JSON.stringify([q.topic,q.module,q.text,q.options,q.correctOptionId,q.explanation,q.sources,q.materials,q.requiredMaterialIds,q.explanationMaterials,q.conversion,q.presentation,q.preserveOrder]);
}
